# Synonym and Alias Registry - runnable demo (JAH-ATK164S-000001)
import re
RANK = 1
SIG = True
REGISTRY = {'myocardial infarction': ['heart attack', 'MI'], 'automobile': ['car', 'motor vehicle'], 'influenza': ['flu'], 'bass fish': ['bass'], 'bass instrument': ['bass']}  # canonical -> [aliases]
def norm(s):
    return re.sub(r"[^a-z0-9 ]", "", s.lower()).strip()
index = {}
for canon, aliases in REGISTRY.items():
    for a in [canon] + aliases:
        index.setdefault(norm(a), []).append(canon)
QUERIES = ["MI", "motor vehicle", "Bass", "flu"]
for q in QUERIES:
    hits = index.get(norm(q), [])
    print("%-14s -> %s" % (q, hits if hits else "NO MATCH"))
if RANK >= 2:
    print("concepts:", len(REGISTRY), "| alias entries:", len(index))
if RANK >= 3:
    amb = {a: cs for a, cs in index.items() if len(cs) > 1}
    print("ambiguous aliases:", amb if amb else "none")
if SIG:
    print("Signature lineage stamp: JAH-SIG-SYN-" + "JAH-ATK164S-000001")
print("record:", "JAH-ATK164S-000001", "OK")

